def build_shared(*,iterations=4,limit=7.,maximum=4,profile_records=False,profile_depth=False):
    """Use the same refinement core for limits and optional profile depths.

    The public wrapper retains its existing interface and immutable settings.
    Only the internal core receives the uniform construction parameters.
    Optional depth stores are bypassed entirely, preserving attribute absence
    as well as values when the caller did not request depth records.
    """
    if (not 1<=iterations<=16 or maximum not in (2,4) or not 1.<limit<8.
            or profile_depth and not profile_records):
        raise ValueError('Invalid shared refinement settings')
    name=f'Prochitecture Streets / Shared quad refinement v1 / {iterations} / {limit:g} / {maximum} / {int(profile_records)} / {int(profile_depth)}'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    core=build(iterations=iterations,limit=7.,maximum=maximum,profile_records=profile_records,
               profile_depth=profile_records,sized_templates=True,_parameter_core=True)
    g=c.Graph(name);g.socket('Geometry','NodeSocketGeometry')
    g.socket('Geometry','NodeSocketGeometry','OUTPUT');g.socket('Valid','NodeSocketBool','OUTPUT')
    g.socket('Strips','NodeSocketGeometry','OUTPUT')
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput')
    call=g.node('GeometryNodeGroup','Shared bounded refinement program');call.node_tree=core
    g.bind(inp.outputs['Geometry'],call.inputs['Geometry'])
    call.inputs['Planning Limit'].default_value=limit;call.inputs['Profile Depth'].default_value=profile_depth
    for key in ('Geometry','Valid','Strips'):g.bind(call.outputs[key],out.inputs[key])
    g.g['st_quad_strip_settings']=dict(iterations=iterations,limit=limit,maximum=maximum,
                                      profile_records=profile_records,profile_depth=profile_depth)
    g.g['st_quad_strip_sized_templates']=1;g.g['st_quad_strip_shared_core']=1
    return g.g


def replace_saved_templates(roots, *, shared_core=False):
    """Opt in private copies of every reachable directional-refinement call.

    Keep constructor settings, native source inputs and all caller guards.
    Interface identifiers must match exactly, so replacing a group cannot
    reorder geometry links or discard a saved modifier input. Original groups
    and defaults remain unchanged. Full scene qualification is still required.
    """
    memo={};changed=[]
    def interface(tree):
        return sorted((s.identifier,s.name,s.in_out,s.socket_type)
                      for s in tree.interface.items_tree if s.item_type=='SOCKET')
    def visit(tree):
        if tree in memo:return memo[tree]
        if tree.get('st_quad_strip_shared_core') or (tree.get('st_quad_strip_sized_templates') and not shared_core):
            memo[tree]=tree;return tree
        if (tree.get('st_quad_strip_settings') is not None or
                tree.name.startswith('Prochitecture Streets / Direct quad strip refinement v1 / ')):
            result=(build_shared(**settings(tree)) if shared_core else build(**settings(tree),sized_templates=True))
            if interface(tree)!=interface(result):
                raise ValueError('Refinement replacement would change saved socket identifiers: '+tree.name)
            changed.append(tree.name)
        else:
            children=[(n.name,visit(n.node_tree)) for n in tree.nodes if n.type=='GROUP' and n.node_tree]
            updates=[(name,child) for name,child in children if child!=tree.nodes[name].node_tree]
            result=tree.copy() if updates else tree
            if updates:result.name='Sized refinement / '+tree.name
            for name,child in updates:
                if interface(tree.nodes[name].node_tree)!=interface(child):
                    raise ValueError('Refinement parent interface changed: '+tree.name)
                result.nodes[name].node_tree=child
        memo[tree]=result
        return result
    results=[visit(root) for root in roots]
    if not changed:raise ValueError('No directional-refinement program found in supplied roots')
    return results,sorted(set(changed))


